const s = msg.payload;

const riesgo = s.risk || 0;
let riesgoEmoji = '🟢';
let riesgoTexto = 'BAJO';
if (riesgo >= 70) { riesgoEmoji = '🔴'; riesgoTexto = 'CRÍTICO'; }
else if (riesgo >= 30) { riesgoEmoji = '🟡'; riesgoTexto = 'MEDIO'; }

const alarmStates = {
    'activada': '🛡️ ACTIVADA',
    'desactivada': '⚪ DESACTIVADA',
    'casa': '🏠 MODO CASA',
    'emergencia': '🚨 EMERGENCIA'
};
const alarmText = alarmStates[s.alarm] || s.alarm;

const bar = (val) => {
    const filled = Math.round(val / 10);
    return '█'.repeat(filled) + '░'.repeat(10 - filled) + ` ${val}%`;
};

const bool = (v) => v ? '🔴 ABIERTA' : '🟢 CERRADA';
const motion = (v) => v ? '🔴 DETECTADO' : '🟢 Normal';

const texto = [
    `🏡 *CASA SEGURA — REPORTE*`,
    `━━━━━━━━━━━━━━━━━━`,
    ``,
    `${riesgoEmoji} *RIESGO: ${riesgoTexto}*`,
    `\`${bar(riesgo)}\``,
    ``,
    `🔔 *Alarma:* ${alarmText}`,
    ``,
    `🚪 *Accesos*`,
    `  • Puerta Principal: ${bool(s.doorMain)}`,
    `  • Puerta Trasera:   ${bool(s.doorBack)}`,
    `  • Ventana Sala:     ${bool(s.winSala)}`,
    `  • Ventana Cocina:   ${bool(s.winCocina)}`,
    ``,
    `🏃 *Sensores PIR*`,
    `  • Sala:       ${motion(s.motionSala)}`,
    `  • Cocina:     ${motion(s.motionCocina)}`,
    `  • Dormitorio: ${motion(s.motionDormitorio)}`,
    ``,
    `━━━━━━━━━━━━━━━━━━`,
    `🕐 ${new Date().toLocaleString('es-EC', { timeZone: 'America/Guayaquil' })}`
].join('\n');

msg.payload = {
    chatId: '5209094665',
    type: 'message',
    content: texto,
    options: { parse_mode: 'Markdown' }
};

return msg;
